import {QUESTIONS,SOURCES,SUBJECTS,TOPIC_NOTES} from './questions.mjs';
import {buildQueue,grade,insertRepeat,remainingSeconds,normalizeState,validatePack,restoreSession,resumeSession,prepareQuestionImport} from './engine.mjs';

const KEY='touun-night-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg={moon:'<path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',repeat:'<path d="m16 3 4 4-4 4M20 7H8a5 5 0 0 0-5 5m5 9-4-4 4-4M4 17h12a5 5 0 0 0 5-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 2 3 4-1 1-3 3-2-1-4-3-1-1-3Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="m14 5-7 7 7 7"/>',star:'<path d="m12 3 2.7 5.6 6.3.9-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.5l6.3-.9Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8Z"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${svg[name]??svg.star}</svg>`;
let storageError=false,raw={};
try{raw=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{storageError=true;}
let custom=[];
try{if(raw.custom?.length)custom=validatePack(raw.custom);}catch{storageError=true;}
let bank=[...QUESTIONS,...custom],state=normalizeState(raw.progress,bank.map(q=>q.id));
let prefs={theme:raw.prefs?.theme==='day'?'day':'night',size:[16,18,20].includes(raw.prefs?.size)?raw.prefs.size:16};
let session=restoreSession(raw.session,bank),view='home',day=initialDay(),filter='all',search='',summary=null,fileMode='questions',pendingImport=null;
function initialDay(){const s=new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'Asia/Seoul'}).format(new Date());return s==='Fri'?2:s==='Sat'?3:1;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({custom,progress:state,prefs,session}));}catch{if(!storageError)toast('저장 공간이 부족해요. 설정에서 기록을 백업해주세요.');storageError=true;}}
function applyPrefs(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.style.setProperty('--base',prefs.size+'px');$('meta[name="theme-color"]').content=prefs.theme==='night'?'#151724':'#f5f1ea';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function navigate(next){if(view==='study'&&next!=='study'&&session&&!session.paused)pauseClock();view=next;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
const qBy=id=>bank.find(q=>q.id===id);
const weakIds=()=>bank.filter(q=>state.stats[q.id]?.seen&&state.stats[q.id]?.lastRating!=='sure').map(q=>q.id);
const minutes=s=>Math.max(0,Math.floor(s/60));
const clock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
function stats(){const seen=bank.filter(q=>state.stats[q.id]?.seen).length,sure=bank.filter(q=>state.stats[q.id]?.lastRating==='sure').length;return {seen,sure,weak:weakIds().length};}
function header(){return `<a class="brand" aria-label="오혜지 합격 기원 지호의 응원" href="#" data-action="home"><img src="icon.svg" alt=""><span class="brand-title">오혜지 합격 기원<span class="brand-subtitle"> 지호의 응원</span></span></a>${view==='study'?`<button class="text-button" data-action="leave">여기까지</button>`:`<span class="header-note">혜지의 합격을 응원하는 지호의 작은 선물</span><button class="icon-button" data-action="theme" aria-label="${prefs.theme==='night'?'밝은 화면으로':'어두운 화면으로'}">${icon(prefs.theme==='night'?'sun':'moon')}</button>`}`;}
function nav(){const items=[['home','home','오늘의 공부'],['review','repeat','다시 보기'],['library','book','자료실'],['settings','settings','설정']];return items.map(([id,ic,label])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('');}
function render(){document.body.classList.toggle('study-mode',view==='study');$('#header').innerHTML=header();$('#nav').innerHTML=nav();$('#main').innerHTML=({home:homeView,study:studyView,summary:summaryView,review:reviewView,library:libraryView,settings:settingsView,add:addView}[view]??homeView)();}
function homeView(){const st=stats();return `${storageError?'<p class="storage-warning">이 브라우저에서 저장이 제한될 수 있어요. 설정에서 기록 백업을 이용해주세요.</p>':''}
 <section class="hero"><div><p class="eyebrow">A LITTLE STUDY, A GOOD NIGHT</p><h1>오늘 외운 게,<br>내일 떠오르도록.</h1><p class="muted">누워서 가볍게, 오늘은 딱 30분만.</p></div><div class="night-art" aria-hidden="true"><div class="orbit"></div><div class="moon"></div><span class="spark">✧</span><span class="spark two">✦</span></div></section>
 <div class="home-grid"><div><section class="panel session-card"><div class="session-top"><div><span class="pill green">${icon('moon')} 오늘의 작은 약속</span><h2>잠들기 전 30분</h2></div><div class="clock-number">30<span>min</span></div></div>
 <div class="day-picks" aria-label="공부할 날 선택">${[[1,'목 · 기초'],[2,'금 · 계산'],[3,'토 · 복습']].map(([id,label])=>`<button class="chip ${day===id?'active':''}" data-action="day" data-day="${id}" aria-pressed="${day===id}">${label}</button>`).join('')}</div>
 <div class="steps"><div class="step"><b>1</b><span>먼저 떠올리고</span><small>보기 전에 생각</small></div><div class="step"><b>2</b><span>한 문제씩 풀고</span><small>짧은 해설·암기</small></div><div class="step"><b>3</b><span>헷갈리면 다시</span><small>간격을 두고 복습</small></div></div>
 ${session?`<button class="primary full" data-action="resume">이어서 공부하기 · ${clock(remainingSeconds(session))} ${icon('arrow')}</button><p class="small muted space-top">진행 중인 공부가 있어요. 이어서 풀거나 마무리할 수 있어요.</p><button class="text-button" data-action="finish-saved">지난 공부 마무리하기</button>`:`<button class="primary full" data-action="start" data-mode="tonight">오늘의 공부 시작 ${icon('arrow')}</button><p class="tiny muted space-top">새 문제 최대 18개 + 짧은 재도전 · 30분이면 마무리 안내</p>`}</section>
 <aside class="night-note cheer-note" aria-label="지호가 보내는 응원">${icon('moon')}<div><p class="eyebrow">지호가 보내는 응원</p><p>혜지야, 오늘도 잘하고 있어.<br>한 문제씩, 네 속도로 해보자.</p><p class="cheer-signature">늘 네 편에서 응원해. — 지호가</p></div></aside></div>
 <div class="stack"><div class="quick-grid"><button class="quick-card" data-action="start" data-mode="weak">${icon('repeat')}<strong>헷갈린 것만</strong><span>${st.weak?`${st.weak}문제, 한 번 더`:'공부하면 여기에 모여요'}</span></button><button class="quick-card" data-action="start" data-mode="bookmarks">${icon('star')}<strong>별표한 문제</strong><span>${state.bookmarks.length}문제 담아뒀어요</span></button></div>
 <section class="panel"><div class="row between"><h3>쌓이고 있는 기억</h3><span class="pill lavender">${st.seen} / ${bank.length}</span></div><p class="tiny muted space-top">문항별로 가장 최근 표시를 모았어요.</p>${[[1,'금융상품'],[2,'분석·위험'],[3,'운용·보호']].map(([id,label])=>{const list=bank.filter(q=>q.subject===id),done=list.filter(q=>state.stats[q.id]?.lastRating==='sure').length;return `<div class="progress-row"><span class="progress-label">${label} <b>${done}</b>/${list.length}</span><div class="progress-bar grow"><i style="width:${done/list.length*100}%"></i></div></div>`;}).join('')}<p class="tiny muted space-top">‘확실히 알았어’로 표시한 문항이에요.<br>시험 예상 점수나 합격 확률을 뜻하지 않아요.</p></section></div></div>
 <p class="footnote">기본 ${QUESTIONS.length}문항은 자체 제작 연습문제이며 공식 기출이 아니에요. 세제·부동산·법규 전체 범위는 교재를 함께 확인해주세요.</p>`;}
function start(mode='tonight',visibleOnly=false){
 if(session){toast('진행 중인 공부를 먼저 이어서 풀거나 마무리해주세요.');navigate('home');return;}
 const pool=visibleOnly?bank.filter(q=>!search||[q.topic,q.prompt,q.memory].some(t=>t.includes(search))):bank;
 const queue=buildQueue(pool,state,{mode,day,limit:18});
 if(!queue.length){toast(mode==='weak'?'아직 헷갈린 문제가 없어요. 오늘의 공부부터 시작해보세요.':'별표한 문제가 없어요. 문제 화면의 별을 눌러 담아보세요.');return;}
 const now=Date.now();session={id:crypto.randomUUID?.()??String(now),queue,index:0,phase:'recall',selected:null,responses:[],duration:1800,elapsed:0,activeSince:now,paused:false,mode,day,startedAt:now};save();navigate('study');
}
function studyView(){if(!session)return homeView();if(session.paused)return `<section class="study-shell pause-screen"><div class="moon-icon">${icon('moon')}</div><p class="eyebrow">A SMALL PAUSE</p><h1 class="space-top">잠깐 쉬어도 괜찮아요.</h1><p class="muted">남은 시간 ${clock(remainingSeconds(session))}<br>문제와 기록은 그대로 기다리고 있어요.</p><div class="pause-cheer"><p>혜지야, 잠깐 쉬어가도 괜찮아.<br>지금까지 해온 너를 믿어.</p><p class="cheer-signature">천천히 해도 돼. 응원해. — 지호가</p></div><button class="primary full" data-action="unpause">다시 시작 ${icon('play')}</button><button class="text-button space-top" data-action="finish-now">오늘은 여기까지</button></section>`;
 const q=qBy(session.queue[session.index]),s=state.stats[q.id],review=session.responses.some(r=>r.id===q.id),answered=session.phase==='feedback',correct=session.selected===q.answer;
 return `<section class="study-shell"><div class="study-heading"><span class="pill lavender">${session.mode==='weak'?'헷갈린 것만':session.mode==='bookmarks'?'별표한 문제':`${session.day}일차 · ${['','기초 다지기','계산 익히기','함정 복습'][session.day]}`}</span><div class="timer"><span id="timer" aria-label="남은 공부 시간">${clock(remainingSeconds(session))}</span><button data-action="pause" aria-label="공부 일시정지">${icon('pause')}</button></div></div>
 <div class="study-progress"><span class="no-wrap">${session.index+1} / ${session.queue.length}문제${review?' · 재도전':''}</span><div class="progress-bar grow"><i style="width:${session.index/session.queue.length*100}%"></i></div></div>
 <div class="question-meta"><span class="topic">${q.subject}과목 · ${esc(q.topic)}</span><button class="icon-button ${state.bookmarks.includes(q.id)?'active':''}" data-action="bookmark" data-id="${esc(q.id)}" aria-label="${state.bookmarks.includes(q.id)?'별표 해제':'별표에 담기'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('star')}</button></div>
 <p class="tiny muted">${q.custom?'내가 추가한 문제':'자체 제작 연습문제'}${s?.seen&&!review?' · 다시 만난 문제':''}</p><h1 class="question-title" id="question-title">${esc(q.prompt)}</h1>
 ${session.phase==='recall'?`<div class="recall-panel"><p class="eyebrow">보기 전에, 5초만</p><p>${esc(q.recall)}</p><p class="small">머릿속으로 답을 떠올려보세요.<br>바로 생각나지 않아도 괜찮아요.</p></div><div class="answer-dock"><button class="primary full" data-action="reveal">생각했어요, 보기 열기 ${icon('arrow')}</button></div>`:`<div class="options" role="group" aria-labelledby="question-title">${q.choices.map((c,i)=>`<button class="option ${session.selected===i?'selected':''} ${answered&&i===q.answer?'correct':''} ${answered&&session.selected===i&&!correct?'wrong':''}" data-action="choose" data-choice="${i}" ${answered?'disabled':''} aria-pressed="${session.selected===i}"><span class="letter">${answered&&i===q.answer?'✓':String(i+1)}</span><span>${esc(c)}${answered&&i===q.answer?' <span class="small">· 정답</span>':''}</span></button>`).join('')}</div>
 ${answered?`<div class="feedback" id="feedback"><p class="feedback-status ${correct?'':'wrong'}">${icon(correct?'check':'repeat')}${correct?'맞았어요. 이제 이유까지 기억해봐요.':'괜찮아요. 이 차이를 기억하면 돼요.'}</p><p class="explanation">${esc(q.explanation)}</p><div class="memory"><small>이 한 줄만 가져가요</small><p>${esc(q.memory)}</p></div><p class="source-line">개념 참고: ${sourceLink(q)}<br>${q.custom?'등록한 자료의 정답·해설을 기준으로 복습해요.':'참고 개념을 바탕으로 직접 만든 문제예요.'}</p><p class="rating-help">${correct?'맞혔는지보다, 확실했는지가 중요해요.':'틀린 문제는 간격을 두고 다시 만나고, 다음 공부에도 먼저 나와요.'}</p><div class="answer-dock"><div class="ratings">${correct?`<button class="rating" data-action="rate" data-rating="guess">찍어서 맞혔어</button><button class="rating sure" data-action="rate" data-rating="sure">확실히 알았어 ${icon('check')}</button>`:`<button class="rating sure" data-action="rate" data-rating="again">한 번 더 기억할게 ${icon('arrow')}</button>`}</div></div></div>`:`<div class="answer-dock"><button class="primary full" data-action="submit" ${session.selected===null?'disabled':''}>정답 확인하기 ${icon('arrow')}</button><p class="tiny muted" style="text-align:center;margin-top:8px">보기를 고른 뒤 확인해주세요.</p></div>`}`}</section>`;
}
function sourceLink(q){return q.sourceUrl?`<a href="${esc(q.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(q.source)}</a>`:esc(q.source);}
function pauseClock(){if(!session||session.paused)return;session.elapsed=1800-remainingSeconds(session);session.paused=true;session.activeSince=Date.now();save();}
function unpause(){if(!session)return;session=resumeSession(session);save();navigate('study');}
function record(rating){if(!session||session.phase!=='feedback')return;const id=session.queue[session.index],q=qBy(id),correct=session.selected===q.answer,effective=correct?rating:'again',review=session.responses.some(r=>r.id===id);state=grade(state,id,correct,effective);session.responses.push({id,correct,rating:effective,review,at:Date.now()});session.phase='recall';session.selected=null;if(effective!=='sure'&&session.queue.length<36)session.queue=insertRepeat(session.queue,session.index,id);session.index++;}
function rate(rating){if(!session||session.phase!=='feedback')return;record(rating);if(session.index>=session.queue.length||remainingSeconds(session)<=0){finish();return;}save();render();window.scrollTo({top:0,behavior:'instant'});$('#question-title')?.scrollIntoView({block:'start',behavior:'instant'});}
function finish(){if(!session)return;if(session.phase==='feedback')record(session.selected===qBy(session.queue[session.index])?.answer?'guess':'again');const seconds=1800-remainingSeconds(session),first=session.responses.filter(r=>!r.review);summary={...session,seconds,first,expired:remainingSeconds(session)<=0};if(!state.history.some(h=>h.id===session.id)&&first.length)state.history.push({id:session.id,at:Date.now(),total:first.length,correct:first.filter(r=>r.correct).length,seconds});state.history=state.history.slice(-60);session=null;save();navigate('summary');}
function summaryView(){if(!summary)return homeView();const first=summary.first,missed=[...new Set(summary.responses.filter(r=>r.rating!=='sure').map(r=>r.id))].slice(0,5),confident=new Set(summary.responses.filter(r=>r.rating==='sure').map(r=>r.id));return `<section class="summary-shell"><div class="summary-hero"><div class="summary-mark">☾</div><p class="eyebrow">YOU DID ENOUGH FOR TONIGHT</p><h1>오늘의 공부는 여기까지.</h1><p class="muted">${summary.expired?'30분이 되었어요. 이제 편히 쉬어요.':'조금씩 떠올린 시간도 분명히 쌓이고 있어요.'}</p><div class="summary-cheer"><p>혜지야, 오늘도 정말 수고했어.<br>오늘 해낸 만큼만 믿고, 이제 푹 자자.</p><p class="cheer-signature">합격하는 날까지, 늘 네 편이야. — 지호가</p></div></div><div class="summary-stats"><div class="stat"><strong>${(summary.seconds<60?'&lt;1':minutes(summary.seconds))}<small>분</small></strong><span>함께한 시간</span></div><div class="stat"><strong>${first.filter(r=>r.correct).length}<small> / ${first.length}</small></strong><span>첫 시도 정답</span></div><div class="stat"><strong>${confident.size}<small>개</small></strong><span>확실히 알았어</span></div></div><p class="tiny muted">재도전은 첫 시도 정답 수에 중복해서 세지 않았어요.<br>학습 결과이며 실제 시험 점수를 예측하지 않아요.</p><div class="section-title"><h2>잠들기 전, 마지막 기억</h2><span class="pill">${missed.length}개</span></div>${missed.length?`<p class="small muted">오늘 헷갈렸던 개념이에요. 힌트만 보고 한 번 떠올려보세요.</p>${missed.map(id=>{const q=qBy(id);return `<article class="recap-card"><small>${esc(q.topic)}</small><p>${esc(q.recall)}</p><details><summary>기억 한 줄 확인 ${icon('arrow')}</summary><p>${esc(q.memory)}</p></details></article>`;}).join('')}`:`<div class="empty">${first.length?'오늘은 헷갈린 표시가 없었어요.<br>다음 공부에서 다시 떠올려봐요.':'아직 푼 문제가 없어요.<br>내일 가볍게 다시 시작해봐요.'}</div>`}<div class="panel space-top"><p class="small">내일은 오늘 헷갈린 것부터.</p><p class="tiny muted space-top">문제·확신 표시를 이 브라우저에 저장했어요.<br>다른 기기에서 이어가려면 설정에서 백업해주세요.</p></div><button class="primary full space-top" data-action="home">잘 자요, 오늘도 수고했어요 ${icon('moon')}</button></section>`;}
function reviewView(){const ids=filter==='bookmarks'?state.bookmarks:filter==='sure'?bank.filter(q=>state.stats[q.id]?.lastRating==='sure').map(q=>q.id):weakIds();const list=bank.filter(q=>ids.includes(q.id)&&(!search||[q.topic,q.prompt,q.memory].some(t=>t.includes(search))));return `<section class="review-shell"><p class="eyebrow">ONE MORE TIME</p><h1 class="space-top">다시 보면, 더 선명하게.</h1><p class="small muted space-top">틀린 문제와 찍어서 맞힌 문제를 모았어요.</p><div class="tabs" aria-label="복습 목록">${[['all','헷갈린 것'],['bookmarks','별표한 것'],['sure','확실한 것']].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-action="filter" data-filter="${id}">${label}</button>`).join('')}</div><input type="search" id="search" placeholder="개념이나 문제 찾기" aria-label="문제 검색" value="${esc(search)}">${list.length&&filter!=='sure'?`<button class="primary full" data-action="start" data-mode="${filter==='bookmarks'?'bookmarks':'weak'}">이 문제들 복습하기 ${icon('arrow')}</button>`:''}<p class="tiny muted space-top">${list.length}문제 · 누르면 해설을 볼 수 있어요.</p><div class="question-list space-top">${list.length?list.map(questionRow).join(''):'<div class="empty">아직 모인 문제가 없어요.<br>오늘의 공부에서 한 문제씩 시작해봐요.</div>'}</div></section>`;}
function questionRow(q){const s=state.stats[q.id];return `<button class="question-row" data-action="inspect" data-id="${esc(q.id)}"><div class="list-top"><span class="pill lavender">${esc(q.topic)}</span><small>${s?.lastRating==='sure'?'확실해':s?.lastRating==='guess'?'찍어서 맞힘':s?.seen?'다시 볼 것':'아직 안 풀었어요'}</small></div><p>${esc(q.prompt)}</p></button>`;}
function libraryView(){return `<section class="library-shell"><p class="eyebrow">YOUR LITTLE LIBRARY</p><h1 class="space-top">공부할 자료를 한곳에.</h1><p class="small muted space-top">기본 ${QUESTIONS.length}문항 + 내 문제 ${custom.length}문항</p><div class="panel space-top"><h3>기본 문제는 어떻게 만들었나요?</h3><p class="small muted space-top">공식 교육자료의 개념을 참고해 직접 만든 연습문제예요. 실제 기출이나 출판사 문제를 복사한 자료가 아니에요.</p><p class="small muted space-top">${TOPIC_NOTES}</p><p class="tiny muted space-top">개념 참고 링크 확인: 2026.11.05 · 참고 자료의 과거 제도·세율·기한은 문제에 옮기지 않았어요.</p></div><div class="section-title"><h2>내 교재 문제 추가</h2></div><p class="small muted">사용할 권한이 있는 문제·정답·해설을 직접 입력하거나 JSON 문제 팩으로 가져올 수 있어요. 이 휴대폰 안에만 저장돼요.</p><div class="button-row space-top"><button class="secondary" data-action="add">${icon('plus')} 직접 입력</button><button class="secondary" data-action="import-questions">${icon('download')} 문제 팩 가져오기</button></div><button class="text-button" data-action="template">JSON 양식 내려받기</button><p class="tiny muted">이 버전은 PDF·사진을 자동으로 읽지 않아요. 자료의 정답·해설을 확인해 등록해주세요.</p>${custom.length?`<details class="space-top"><summary>내가 추가한 ${custom.length}문제 보기</summary><div class="question-list space-top">${custom.map(questionRow).join('')}</div></details>`:''}<div class="section-title"><h2>개념 참고자료</h2><span class="pill">공식 기관</span></div>${SOURCES.filter(s=>!s.external).map(sourceCard).join('')}<div class="section-title"><h2>교재·무료 자료 안내</h2></div><p class="small muted" style="margin-bottom:16px">자료 제공·인증 조건은 원문에서 확인해주세요. 무료 다운로드와 앱 재배포 허용은 다를 수 있어 원문을 앱에 넣지 않았어요.</p>${SOURCES.filter(s=>s.external).map(sourceCard).join('')}</section>`;}
const sourceCard=s=>`<article class="source-card"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><p>${esc(s.note)}</p></article>`;
function settingsView(){return `<section class="settings-shell"><p class="eyebrow">MAKE YOURSELF COMFORTABLE</p><h1 class="space-top">편안한 공부를 위해.</h1><div class="setting-row section-gap"><div><h3>화면 색</h3><p>잠들기 전에는 어두운 화면으로.</p></div><select id="theme-select" aria-label="화면 색"><option value="night" ${prefs.theme==='night'?'selected':''}>밤의 화면</option><option value="day" ${prefs.theme==='day'?'selected':''}>낮의 화면</option></select></div><div class="setting-row"><div><h3>글자 크기</h3><p>잘 보이는 크기로 맞춰주세요.</p></div><select id="size-select" aria-label="글자 크기">${[[16,'기본'],[18,'크게'],[20,'더 크게']].map(([n,l])=>`<option value="${n}" ${prefs.size===n?'selected':''}>${l}</option>`).join('')}</select></div><div class="section-title"><h2>내 공부 기록</h2></div><div class="panel"><p class="small">기록은 지금 이 브라우저에만 있어요.</p><p class="small muted space-top">서버로 보내지 않아요. 브라우저 데이터를 지우거나 다른 기기로 옮기면 자동으로 이어지지 않으니 백업을 이용해주세요.</p><div class="button-row space-top"><button class="secondary" data-action="export">기록 백업</button><button class="secondary" data-action="import-backup">백업 가져오기</button></div><p class="tiny muted space-top">가져오기는 기존 기록을 보존하고, 문제별 최신 기록을 합쳐요. 진행 중인 세션은 옮기지 않아요.</p></div><div class="section-title"><h2>이렇게 기억해보세요</h2></div><div class="stack small muted"><p>① 보기 전에 개념을 머릿속으로 한 번 떠올리기.</p><p>② 맞혀도 확신이 없었다면 ‘찍어서 맞혔어’로 표시하기.</p><p>③ 해설을 읽은 뒤 화면을 잠깐 보지 않고 암기 한 줄을 말해보기.</p><p>④ 헷갈린 문제는 같은 밤에 간격을 두고, 다음 밤에 한 번 더 보기.</p></div><p class="footnote">3일 복습용 보조 도구예요. 기본 문제는 전 범위를 포함하지 않으며, 합격이나 기억 유지를 보장하지 않아요.</p></section>`;}
function addView(){return `<section class="library-shell"><button class="text-button" data-action="nav" data-view="library">‹ 자료실로</button><h1>내 교재 문제 추가</h1><p class="small muted space-top">직접 쓴 내용이나 사용할 권한이 있는 자료만 등록해주세요.</p><form id="question-form" class="form-grid"><label>과목<select name="subject">${Object.entries(SUBJECTS).map(([n,label])=>`<option value="${n}">${n}과목 · ${label}</option>`).join('')}</select></label><label>개념 이름<input name="topic" maxlength="100" placeholder="예: 듀레이션" required></label><label>문제<textarea name="prompt" maxlength="5000" required></textarea></label>${[1,2,3,4].map(n=>`<label>보기 ${n}${n>2?' (선택)':''}<input name="choice${n}" maxlength="1000" ${n<3?'required':''}></label>`).join('')}<label>정답 번호<select name="answer">${[1,2,3,4].map(n=>`<option value="${n-1}">${n}번</option>`).join('')}</select></label><label>정답의 이유<textarea name="explanation" maxlength="5000" required></textarea></label><label>기억할 한 줄<input name="memory" maxlength="500" placeholder="예: 샤프는 표준편차, 트레이너는 베타"></label><label>보기 전 힌트<input name="recall" maxlength="500" placeholder="정답을 바로 알려주지 않는 질문"></label><label>출처·교재 쪽수<input name="source" maxlength="200" placeholder="예: 내 문제집 125쪽"></label><label>출처 링크 (선택)<input name="sourceUrl" type="url" maxlength="1500" placeholder="https://"></label><button type="submit" class="primary">내 문제로 저장하기</button></form></section>`;}
function openModal(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function inspect(id){const q=qBy(id);if(!q)return;openModal(`<div class="modal-title"><h2>${esc(q.topic)}</h2><button class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div><p>${esc(q.prompt)}</p><p style="color:var(--green)">정답 · ${esc(q.choices[q.answer])}</p><p>${esc(q.explanation)}</p><div class="memory"><small>기억 한 줄</small><p>${esc(q.memory)}</p></div><p class="source-line">${sourceLink(q)}</p><button class="secondary full" data-action="modal-bookmark" data-id="${esc(id)}">${icon('star')} ${state.bookmarks.includes(id)?'별표 해제':'별표에 담기'}</button>`);}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportBackup(){download(`투운사-공부기록-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({format:'touun-night-backup',version:1,customQuestions:custom,progress:state},null,2));toast('공부 기록을 내려받았어요.');}
function importFile(mode){fileMode=mode;$('#file-input').value='';$('#file-input').click();}
function prepareImport(data){
 if(fileMode==='backup'){
  if(data?.format!=='touun-night-backup'||data.version!==1)throw new Error('이 앱에서 만든 백업 파일을 선택해주세요.');
  const incoming=data.customQuestions?.length?validatePack(data.customQuestions):[];
  if(incoming.some(q=>QUESTIONS.some(b=>b.id===q.id)))throw new Error('기본 문제와 ID가 겹치는 백업이에요.');
  pendingImport={kind:'backup',questions:incoming,progress:data.progress};
 }else{pendingImport={kind:'questions',questions:prepareQuestionImport(data)};}
 const existing=new Set(bank.map(q=>q.id)),fresh=pendingImport.questions.filter(q=>!existing.has(q.id));if(custom.length+fresh.length>500)throw new Error('내 문제는 모두 합쳐 500개까지 저장할 수 있어요.');
 openModal(`<h2>${pendingImport.kind==='backup'?'기록을 합칠까요?':'문제를 가져올까요?'}</h2><p>새 문제 ${fresh.length}개를 추가해요. 같은 ID의 문제는 기존 내용을 유지해요.${pendingImport.kind==='backup'?'<br>문제별로 더 최근에 공부한 기록을 적용하고, 별표를 합쳐요.':''}</p><button class="primary full" data-action="confirm-import">가져오기</button><button class="secondary full" data-action="cancel-import">취소</button>`);
}
function confirmImport(){if(!pendingImport)return;const existing=new Set(bank.map(q=>q.id)),fresh=pendingImport.questions.filter(q=>!existing.has(q.id));custom.push(...fresh);bank=[...QUESTIONS,...custom];if(pendingImport.kind==='backup'){const incoming=normalizeState(pendingImport.progress,bank.map(q=>q.id));for(const [id,s]of Object.entries(incoming.stats))if(!state.stats[id]||(s.lastAt??0)>(state.stats[id].lastAt??0))state.stats[id]=s;state.bookmarks=[...new Set([...state.bookmarks,...incoming.bookmarks])];state.history=[...new Map([...state.history,...incoming.history].map(h=>[h.id,h])).values()].sort((a,b)=>a.at-b.at).slice(-60);}pendingImport=null;save();$('#modal').close();navigate('library');toast('자료와 기록을 가져왔어요.');}
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;e.preventDefault();
 if(a==='home')navigate('home');
 else if(a==='nav')navigate(el.dataset.view);
 else if(a==='theme'){prefs.theme=prefs.theme==='night'?'day':'night';applyPrefs();save();render();}
 else if(a==='day'){day=Number(el.dataset.day);render();}
 else if(a==='start')start(el.dataset.mode,view==='review');
 else if(a==='resume'){if(session){if(remainingSeconds(session)<=0)finish();else unpause();}}
 else if(a==='pause'){pauseClock();render();}
 else if(a==='unpause')unpause();
 else if(a==='leave'){pauseClock();render();}
 else if(a==='finish-now'||a==='finish-saved')finish();
 else if(a==='reveal'&&session?.phase==='recall'){session.phase='choices';save();render();}
 else if(a==='choose'&&session?.phase==='choices'){session.selected=Number(el.dataset.choice);save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);}
 else if(a==='submit'&&session?.phase==='choices'&&session.selected!==null){session.phase='feedback';save();render();$('#feedback')?.scrollIntoView({behavior:'smooth',block:'start'});}
 else if(a==='rate')rate(el.dataset.rating);
 else if(a==='bookmark'||a==='modal-bookmark'){const id=el.dataset.id;if(!qBy(id))return;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();if(a==='modal-bookmark')inspectUpdate(id);else{const scroll=window.scrollY;render();window.scrollTo(0,scroll);}toast(state.bookmarks.includes(id)?'별표에 담았어요.':'별표를 해제했어요.');}
 else if(a==='filter'){filter=el.dataset.filter;render();}
 else if(a==='inspect')inspect(el.dataset.id);
 else if(a==='close-modal')$('#modal').close();
 else if(a==='add')navigate('add');
 else if(a==='template')download('투운사-문제양식.json',JSON.stringify({questions:[{id:'my-001',subject:2,topic:'예시 개념',day:1,prompt:'문제를 적어주세요.',choices:['보기 1','보기 2','보기 3','보기 4'],answer:0,explanation:'정답이 1번인 이유를 적어주세요. answer는 0부터 시작해요.',memory:'기억할 한 줄',recall:'보기 전에 떠올릴 힌트',source:'내 교재 00쪽',sourceUrl:''}]},null,2));
 else if(a==='export')exportBackup();
 else if(a==='import-questions')importFile('questions');
 else if(a==='import-backup')importFile('backup');
 else if(a==='confirm-import')confirmImport();
 else if(a==='cancel-import'){pendingImport=null;$('#modal').close();}
});
function inspectUpdate(id){$('#modal').close();inspect(id);}
document.addEventListener('change',e=>{if(e.target.id==='theme-select'){prefs.theme=e.target.value;applyPrefs();save();}else if(e.target.id==='size-select'){prefs.size=Number(e.target.value);applyPrefs();save();}});
function refreshSearch(e){if(e.target.id!=='search')return;search=e.target.value;if(e.isComposing)return;const focus=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(focus,focus);}
document.addEventListener('input',refreshSearch);
document.addEventListener('compositionend',refreshSearch);
$('#file-input').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('파일은 2MB 이하로 선택해주세요.');prepareImport(JSON.parse(await file.text()));}catch(error){pendingImport=null;toast(error instanceof SyntaxError?'JSON 파일 형식을 확인해주세요.':error.message);}});
document.addEventListener('submit',e=>{if(e.target.id!=='question-form')return;e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),choices=[d.choice1,d.choice2,d.choice3,d.choice4];while(choices.length>2&&!choices.at(-1).trim())choices.pop();if(choices.some(c=>!c.trim()))throw new Error('보기는 중간 번호를 비우지 말고 입력해주세요.');if(custom.length>=500)throw new Error('내 문제는 500개까지 저장할 수 있어요.');const [q]=validatePack([{...d,id:`local-${crypto.randomUUID?.()??Date.now()}`,subject:Number(d.subject),answer:Number(d.answer),day:day,choices}]);custom.push(q);bank=[...QUESTIONS,...custom];save();navigate('library');toast('내 문제를 저장했어요.');}catch(error){toast(error.message);}});
setInterval(()=>{if(view!=='study'||!session||session.paused)return;const seconds=remainingSeconds(session);if($('#timer'))$('#timer').textContent=clock(seconds);if(seconds<=0){finish();toast('30분이 되었어요. 오늘은 여기까지, 편히 쉬어요.');}},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
window.addEventListener('pagehide',save);
applyPrefs();render();
